+	const runCount = readRunCount(value.runCount);
+	const errorMessage =
+		typeof value.errorMessage === "string" ? value.errorMessage.trim() : "";
+	if (!errorMessage || !Number.isFinite(createdAt) || runCount === undefined) {
+		return undefined;
+	}
+	return { runCount, createdAt, errorMessage };
